window.SAQ_PAPER_QUESTIONS["2020-2-pah"]=[{"number":1,"title":"","stemText":"A 54 year old woman has presented to the ED with an isolated right ankle injury.\nShe has no other medical problems. An x-ray of her right ankle is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 3 radiographic abnormalities. (3 marks)"},{"id":"b","label":"Part B","prompt":"Classify the injury and state its clinical relevance. (2 marks)"},{"id":"c","label":"Part C","prompt":"Other than procedural sedation, state 4 components of your management of this patient. (4 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"You are planning to provide procedural sedation as part of your management."},{"id":"e","label":"Part E","prompt":"State 4 components of your airway examination and indicate what findings might make\nintubation difficult. (4 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"},{"id":"f","label":"Part F","prompt":"List 5 potential acute complications of procedural sedation and state how you would\nmanage each complication. (10 marks) Complication Management"}],"propPages":["asset:img498cf890858f30b9cb"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>17/23</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Analgesia – something parenteral ie morphine 5mg IV</div><div class=\"answer-line\"><strong>Closed reduction  </strong></div><div class=\"answer-line\">immobilization in slab</div><div class=\"answer-line\">Elevation</div><div class=\"answer-line\">Admission for ORIF</div><div class=\"answer-line\">4.</div><div class=\"answer-line\">Mouth Opening: Impaired mouth opening, Large Teeth, Big tongue (OP crowding)</div><div class=\"answer-line\">Mallampati View 3/4</div><div class=\"answer-line\">Mandible anatomy - Small jaw, Thyromental distance, Anterior Larynx</div><div class=\"answer-line\">Neck assessment: Thyromental distance, Anterior Larynx, mobility</div><div class=\"answer-line\">5.</div><div class=\"answer-line\">Intrasedation:</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Aspiration – suction, antiemetics, oxygen</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Hypoxia – supplemental O2, airway adjuncts if upper airway tone/obstruction concerns</div><div class=\"answer-line\">Emergence Phenomena/Disinhibition – destimulus, reassurance, consider additional</div><div class=\"answer-line\">pharmacotherapy ie midazolam</div><div class=\"answer-line\">Hypotension – IV fluid load 0.9% saline, use of parenteral vasopressor ie metaraminol</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Mouth Opening: Impaired mouth opening, Large Teeth, Big tongue (OP crowding)</div><div class=\"answer-line\">Mallampati View 3/4</div><div class=\"answer-line\">Mandible anatomy - Small jaw, Thyromental distance, Anterior Larynx</div><div class=\"answer-line\">Neck assessment: Thyromental distance, Anterior Larynx, mobility</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Intrasedation:</div><div class=\"answer-line\">Laryngospasm: management – PEEP, increase sedation (ie bolus propofol), paralyse and intubate if</div><div class=\"answer-line\">not able to break spasm)</div><div class=\"answer-line\">Aspiration – suction, antiemetics, oxygen</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">Hypoventilation – expectant management usually sufficient, BVM support if prolonged</div><div class=\"answer-line\">Hypoxia – supplemental O2, airway adjuncts if upper airway tone/obstruction concerns</div><div class=\"answer-line\">Emergence Phenomena/Disinhibition – destimulus, reassurance, consider additional</div><div class=\"answer-line\">pharmacotherapy ie midazolam</div><div class=\"answer-line\">Hypotension – IV fluid load 0.9% saline, use of parenteral vasopressor ie metaraminol</div><div class=\"answer-line\">Inadequate sedation/breakthrough pain – titratable sedation/analgesic agent ie propofol/fentanyl or</div><div class=\"answer-line\">titrated ketamine aliquots</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 33 year old man has presented to the ED with a fever.\nHe has returned from Papua New Guinea 7 days ago.","parts":[{"id":"a","label":"Part A","prompt":"State 6 features of your history that will help delineate the cause of his fever. Include a brief explanation for each feature. (6 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ 6) ________________________________________________________________________________ On your initial assessment, there is no obvious cause of fever. The patient’s other vital signs are normal."},{"id":"b","label":"Part B","prompt":"List and justify 6 investigations you might perform. (6 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ 6) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Nature of fever – ie cyclical (malaria)</td><td>Timing of onset ie if &gt;5 days post return then not consistent with dengue</td></tr><tr><td>Associated symptoms ie rash, arthralgia – dengue</td><td>History of bites/stings – arthropod-borne infections more likely</td></tr><tr><td>IV Drug Use or other percutaneous exposures ie tattoos</td><td>Unknown/high-risk sexual encounters ie sex workers</td></tr><tr><td>History of prophylaxis for malaria</td><td>Exposure to possibly contaminated water sources – protozoal infections</td></tr><tr><td>Localising symptoms – ie cough, dysuria etc</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Blood Film – evidence of parasites or haemolysis</div><div class=\"answer-line\">CXR – exclude pneumonia/abscess</div><div class=\"answer-line\">Urinalysis – exclude UTI</div><div class=\"answer-line\"><strong>Dengue Serology – exclude dengue </strong></div><div class=\"answer-line\">Thick/Thin Films for malaria – identify subtype and degree of parasitosis</div><div class=\"answer-line\">Blood Cultures – confirm pathogen/bacteraemia and refine therapy</div><div class=\"answer-line\">Others ie ECHO, NPA, urine PCR, Sputum MCS guided by above</div><div class=\"answer-line\">Malaria Ag tests</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 28 year old man has been brought to the ED with palpitations and pre-syncope.\nHis ECG is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"Give your overall interpretation of the ECG, supported by 4 abnormalities. (6 marks) Overall interpretation (2 marks) Supportive abnormalities (4 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ The patient has the following vital signs:\n\nGCS\n\nBP\n80/40 mmHg O2 sats 98% room air\n\nRR\n/min You have decided to electrically cardiovert the patient."},{"id":"b","label":"Part B","prompt":"State 5 steps to safely perform this procedure. (5 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________"}],"propPages":["asset:imga5e771a6c129b80a28"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Atrial Fibrillation with pre-excitation (WPW)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Very fast (198/min)</div><div class=\"answer-line\">Irregularly Irregular</div><div class=\"answer-line\">Broad QRS</div><div class=\"answer-line\">Delta Waves (seen best in V3)</div><div class=\"answer-line\">3.</div><div class=\"answer-line\">Consent</div><div class=\"answer-line\">Paddles + Monitor</div><div class=\"answer-line\">Sedation/Analgesia ie Fentanyl 50mcg + Midazolam 1mg or similar</div><div class=\"answer-line\">Synchronised Mode</div><div class=\"answer-line\">Shock at 200J</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 28 year old woman has presented to the ED with 3 days of severe headache.","parts":[{"id":"a","label":"Part A","prompt":"List and justify 6 features of your examination. (6 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ 6) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 5 specific indications for a CT scan in this situation. Provide the pathological\nabnormality for which you will be looking. (5 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Temperature – Fever suggestive of infectious causes ie meningoencephalitis</div><div class=\"answer-line\">Fundoscopy – Papilloedema to identify raised ICP</div><div class=\"answer-line\">Focal Neurology – ie posturing/paresis  - suggests focal lesion ie cerebritis/abscess</div><div class=\"answer-line\">Cranial Nerve exam – ie eye lesions – suspicions for cavernous sinus thrombosis</div><div class=\"answer-line\">Examination for gravid uterus – increased risk for pre-eclampsia</div><div class=\"answer-line\">Neck Exam for meningism/rigidity - ?subarach irritation or infection</div><div class=\"answer-line\">Mental State Exam – disorientation, confusion concerning for infection</div><div class=\"answer-line\">Photosensitivity – suggestive of cerebral irritation, migraine</div><div class=\"answer-line\">Facial findings ie tearing, rhinorrhea and red eye – suggestive of cluster headache</div><div class=\"answer-line\">Hyperreflexia – suggestive of CNS irritation/raised ICP</div><div class=\"answer-line\">Vision exam – impairment concerning for posterior circulation lesion or PRES syndrome</div><div class=\"answer-line\">Ataxia/cerebellar signs – Vertebral Artery Dissection</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">History of sudden onset - ?Subarachnoid Haemorrhage</div><div class=\"answer-line\">Findings of focal neurology – suggest focal lesion ie malignancy, abscess, cerebritis, infarction</div><div class=\"answer-line\">Extraocular nerve palsies or exopthalmus – suggestive of cavernous sinus thrombosis</div><div class=\"answer-line\">Altered Conscious State – makes clinical assessment difficult – will aid in identification of key</div><div class=\"answer-line\">differentials ie SAH, mass lesion etc</div><div class=\"answer-line\">Findings concerning for raised ICP – hypertension, hyperreflexia, papilloedema – CT to exclude mass</div><div class=\"answer-line\">lesion, central venous sinus thrombosis</div><div class=\"answer-line\">Others ie Focal Seizure acceptable if justified</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 2 year old boy has been taken to hospital with fever and difficulty breathing.\nHe has no previous medical problems His chest x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State your provisional diagnosis, supported by 2 radiographic abnormalities. (3 marks) Your assessment is that the child is appropriate for admission to a general ward. He is not tolerating\n• ral therapy."},{"id":"b","label":"Part B","prompt":"State 3 components of your management, including end-points where appropriate.\n(3 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"List 3 common microbiological causes of this condition. (3 marks)"},{"id":"d","label":"Part D","prompt":"List 3 investigations you could perform to determine the microbiological cause. (3 marks)"}],"propPages":["asset:img01265b1279c04f45a8"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Right Upper Lobe Collapse/Consolidation – given fever diagnosis is Pneumonia</div><div class=\"answer-line\">Supportive Features</div><div class=\"answer-line\">Opacification RUL</div><div class=\"answer-line\">Elevation Rt Horizontal Fissure</div><div class=\"answer-line\">Air Bronchogram at inferomedial aspect of consolidation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Antibiotics – IV</strong> BenPen 50mg/kg q6hrly ie 600mg for 12kg weight</div><div class=\"answer-line\">Oxygen – to maintain Sats &gt;94%</div><div class=\"answer-line\">Maintenance Fluids – IV – Assume weight is 12kg  = 44mls/hr 0.9% Saline + 5% Dextrose</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Respiratory Viruses</div><div class=\"answer-line\">Strep Pneumoniae</div><div class=\"answer-line\">Mycoplasma Pneumoniae</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">NPA for Resp Viruses</div><div class=\"answer-line\">Blood Culture</div><div class=\"answer-line\">Sputum Culture</div><div class=\"answer-line\">Strep Ag testing</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 25 year old man has presented to the ED with a swollen left hemiscrotum.","parts":[{"id":"a","label":"Part A","prompt":"List 6 differential diagnoses. For each, state the examination findings that would support the diagnosis. (12 marks) Diagnosis Examination findings"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Torsion </strong>– high riding testicle, horizontal lie, loss of cremasteric reflex</td><td>Epididymitis – penile discharge, fever, pyuria</td></tr><tr><td>Orchitis – systemic illness ie mumps (parotitis)</td><td>Haematocoele – trauma to hemiscrotum</td></tr><tr><td>Malignancy – painless, irregular mass</td><td>Varicocoele – left-sided, ‘bag of worms”</td></tr><tr><td>Indirect Inguinal Hernia – can get below mass</td><td>Hydrocoele – transilluminates</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 35 year old man has been referred by his GP with anaemia.\nHis blood results are provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State and justify your provisional diagnosis. (4 marks) Provisional Diagnosis Justification The patient has normal vital signs."},{"id":"b","label":"Part B","prompt":"List 6 components of your clinical assessment (history, examination or investigation) of\nthis patient. Briefly explain the relevance of each. (6 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ 6) ________________________________________________________________________________"}],"propPages":["asset:imgbd9c1a9b5fbf1dc944"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>6/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Haemolytic Anaemia</div><div class=\"answer-line\">Isolated Anaemia</div><div class=\"answer-line\">Elevated markers of cell breakdown (unconjugated hyperbilirubinaemia, high LDH)</div><div class=\"answer-line\">Normal GGT/Albumin suggests absence of hepatic cause</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">To determine cause:</div><div class=\"answer-line\">Hx:</div><div class=\"answer-line\">History of sickle cell/thalassaemia</div><div class=\"answer-line\">History of IV drug use</div><div class=\"answer-line\">History of valvular hear disease (intrinsic, valve surgery)</div><div class=\"answer-line\">History of fevers, other recent illness</div><div class=\"answer-line\">Ex:</div><div class=\"answer-line\">Examine for murmurs</div><div class=\"answer-line\">Examine for signs of IE – fever, splinters</div><div class=\"answer-line\">Examine for hypersplenism – splenomegaly</div><div class=\"answer-line\">Ix:</div><div class=\"answer-line\">Further blood tests – Haptoglobin, Free Hb</div><div class=\"answer-line\">Blood Film – Schistocytes to confirm haemolysis, abnormal red cells for Haemoglobinopathies, red</div><div class=\"answer-line\">cell dysplasias</div><div class=\"answer-line\">Hb Electrophoresis for Haemoglobinopathies ie sickle cell/ thalassaemia</div><div class=\"answer-line\">Assess for renal complications – Urea/Creat, urinalysis for Free Hb</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 12 year old girl has been taken to hospital by ambulance with an exacerbation of asthma. She has had minimal response to nebulised salbutamol with the ambulance service. On arrival, her vital signs are:\n\nGCS\nPulse 180 /min\n\nBP\n100/65 mmHg\n\nRR\n/min O2 sats 88% 6L O2 via Hudson mask","parts":[{"id":"a","label":"Part A","prompt":"State 5 components of your initial management of this patient. (5 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ Despite your initial management, the patient deteriorated and required intubation due to fatigue\nwith type 2 respiratory failure.\nA short time after intubation, the patient has developed hypotension."},{"id":"b","label":"Part B","prompt":"List 4 causes of hypotension and state the management of each cause. (8 marks)\nCause of hypotension Management"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>10/13</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Burst Salbutamol</strong> – 3 x 5mg nebs q20min or IV salbutamol 5mg/kg over 5 mins given ambulance has</div><div class=\"answer-line\">given nebs</div><div class=\"answer-line\">Nebulized Ipratropium 0.5mg x 3 q20min</div><div class=\"answer-line\">IV Magnesium 50mg/kg over 10 mins</div><div class=\"answer-line\">IV Steroid Hydrocortisone 4mg/kg (accept PO dose as haven’t stated cannot tolerate oral therapy) –</div><div class=\"answer-line\">pred 1-2mg/kg</div><div class=\"answer-line\">Other options probably reserved at this stage until response</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Tension Pneumothorax</strong> – Unilateral thoracostomy with subsequent intercostal tube placement</div><div class=\"answer-line\">Raised intrathoracic pressure with loss of venous return to right heart – IV fluid bolus 10mls/kg</div><div class=\"answer-line\">Dynamic Hyperinflation – disconnect ventilator to allow deflation and reventilate at a slower rate to</div><div class=\"answer-line\">allow full expiration</div><div class=\"answer-line\">Anaphylaxis to induction agents/sedation drugs – IM adrenaline 10mcg/kg to 300mcg</div><div class=\"answer-line\">Excess sedation – titrate sedatives to a lower dose</div><div class=\"answer-line\">Others ok</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 60 year old woman has been taken to the ED after a high speed motor vehicle accident. She was the driver of a sedan that collided head-on with a truck.\nHer vital signs on arrival are:\n\nGCS\nE3 V4 M5\n\nHR\n100 /min\n\nBP\n80/40 mmHg\n\nRR\n/min O2 sats 99% 15L O2 via non-rebreather mask Her initial chest x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State your provisional diagnosis, supported by 3 radiographic abnormalities. (4 marks) Further assessment reveals no major wounds and no evidence of long bone injury. Pelvic x-ray is normal."},{"id":"b","label":"Part B","prompt":"List 4 potential causes of this patient’s hypotension. Indicate the features on examination\n• r bedside investigation that would support each cause. (8 marks)\nCause of hypotension Examination / investigation features\nPAH 2020.2 trial SAQ paper\nPART 2\nQuestions 10 - 18\n1 hour"}],"propPages":["asset:img381bca0b31ca2831ae"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Blunt Aortic Injury/ Mediastinal Haematoma/Traumatic Aortic Rupture</div><div class=\"answer-line\">Widened paratracheal stripe on Rt</div><div class=\"answer-line\">Widened mediastinum at hilum/carina</div><div class=\"answer-line\">Double aortic contour</div><div class=\"answer-line\">Loss AP window</div><div class=\"answer-line\">Loss aortic knuckle</div><div class=\"answer-line\">Apical Cap</div><div class=\"answer-line\">Depression L mainstem bronchus/Narrowing of interbronchial angle at carina to 90deg</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Tamponade – distended neck veins, facial plethora, effusion on echo</div><div class=\"answer-line\">Neurogenic Shock from disruption of thoracic cord/spinal artery dissection – LL paralysis/spinal</div><div class=\"answer-line\">tenderness/step on log roll</div><div class=\"answer-line\">Acute myocardial contusion with pump failure – conduction block on ECG ie new LBBB / echo LV</div><div class=\"answer-line\">dysfunction</div><div class=\"answer-line\">Coronary Artery Injury with subsequent MI – STEMI on ECG</div><div class=\"answer-line\">Hypovolaemia from Intraperitoneal Haemorrhage – distention/seatbelt bruise, FAST scan positive</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 6 year old boy has been taken to the ED after falling off a scooter and striking his head at a skate park.","parts":[{"id":"a","label":"Part A","prompt":"List 5 findings on history or examination that would indicate the need for an urgent CT\nscan of the patient’s head. (5 marks)"},{"id":"b","label":"Part B","prompt":"List 4 examination findings that would indicate the need for a CT scan of the patient’s\ncervical spine. (4 marks) You elected to perform a CT scan of the head and cervical spine. The cervical spine is normal. An axial slice of the CT head is demonstrated in the PROPS BOOKLET."},{"id":"c","label":"Part C","prompt":"State the key pathology demonstrated on the CT slice with 3 supportive findings. (4 marks) Key pathology Supportive findings On return from the radiology suite, the patient’s consciousness has deteriorated significantly. He has the following vital signs:\n\nGCS\nE2 V3 M4 Pulse 110 /min\n\nBP\n100/65 mmHg\n\nRR\n/min O2 sats 98% room air"},{"id":"d","label":"Part D","prompt":"State 5 components of your management of this patient. (5 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________"}],"propPages":["asset:img5e39623cf48db43c06"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>13/18</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">On History:</div><div class=\"answer-line\">High risk mechanism ie fall &gt;10 steps or similar</div><div class=\"answer-line\">Prolonged LOC ie &gt;5 mins</div><div class=\"answer-line\">Impact Seizure</div><div class=\"answer-line\">On Exam:</div><div class=\"answer-line\">Altered Level of Consciousness</div><div class=\"answer-line\">Ongoing amnesia, disorientation, abnormal behaviour</div><div class=\"answer-line\">Focal Neurology (posturing, lateralising weakness or pupil change)</div><div class=\"answer-line\">Signs of skull fracture (boggy haematoma)</div><div class=\"answer-line\">Signs of BOS fracture (with specific example)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Spinal level on exam</div><div class=\"answer-line\">Limb weakness</div><div class=\"answer-line\">Neurogenic shock ie brady, vasodilated</div><div class=\"answer-line\">Step deformity</div><div class=\"answer-line\">Other local exam findings ie marked tenderness, bruising</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Supportive findings:</div><div class=\"answer-line\">Hyperdense extraaxial collection</div><div class=\"answer-line\">Biconvex, not crossing suture lines</div><div class=\"answer-line\">Swirl sign</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Hyper-Ventilate to CO2 30</div><div class=\"answer-line\">Head up 30deg given normal C-spine</div><div class=\"answer-line\">Hypertonic Saline 3mls/kg/3% or similar or Mannitol 0.5-1 gm/kg to lower ICP whilst awaiting OT</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 32 year old man has been brought to the ED with a prolonged seizure.","parts":[{"id":"a","label":"Part A","prompt":"List 6 potential causes for the seizure. For each cause, list a cardinal assessment feature (history, examination or investigation) that would support its presence. (12 marks) Cause of seizure Assessment feature"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Known Seizure disorder ie epilepsy – History of same, medicAlert bracelet</td><td>Head Injury with TBI – Signs of CHI – boggy haematoma, abrasions, history of fall/high force decel</td></tr><tr><td>Toxidrome ie venlafaxine OD – suicide note, access to medications, prior OD</td><td>Drug withdrawal – history of chronic benzodiazepine/alcohol use</td></tr><tr><td>Intracranial Mass ie tumour – history of headache, ICP symptoms</td><td>Hyponatraemia – low Na on VBG</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 10 year old boy has presented to the ED with a limp for the last 3 days. He has pain in his left hip when walking.","parts":[{"id":"a","label":"Part A","prompt":"List 5 investigations you might perform. Include the clinical indication for each. (5 marks) Investigation Indication As part of his assessment, a pelvic x-ray has been ordered. It is provided in the PROPS BOOKLET."},{"id":"b","label":"Part B","prompt":"State the likely diagnosis, including the key radiographic supporting finding/s. (2 marks)"},{"id":"c","label":"Part C","prompt":"State 3 components of your management. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":["asset:imgfb94193867b0f702aa"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>6/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Investigation</td><td>Indication</td></tr><tr><td>Xray Lt Hip/Pelvis</td><td>Pain on ROM of hip – to identify bony concerns ie perthes/SCFE</td></tr><tr><td>Accept xray if no alternate cause (ie extraarticular) found on exam</td><td></td></tr><tr><td>trauma</td><td></td></tr><tr><td>USS Hip</td><td>Fever, limited ROM due to pain – to identify effusion ?septic joint</td></tr><tr><td>FBE</td><td>If septic arthritis on differential; WCC considered useful where septic</td></tr><tr><td>arthritis on differential</td><td></td></tr><tr><td>CRP/ESR</td><td>If ?septic arthritis; Both considered criteria in risk stratification for septic</td></tr><tr><td>arthritis</td><td></td></tr><tr><td>Blood Culture</td><td>If febrile – to guide antimicrobial regimen</td></tr><tr><td>Scrotal USS</td><td>If tender hemiscrotum on exam – to identify possible torsion</td></tr><tr><td>COAGs/ Platelets</td><td>If history prior haemarthrosis – suspected atraumatic haemarthrosis ie</td></tr><tr><td>haemophilia</td><td></td></tr><tr><td>CaMgPO4</td><td>If osteopenia on xray imaging – exclude underlying mineralization problem</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Left Slipped Capital Femoral Epiphysis</div><div class=\"answer-line\">Loss of Line of Klein</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia – PO paracetamol 15mg/kg, ibuprofen 10mg/kg</div><div class=\"answer-line\">Admit orthopaedics</div><div class=\"answer-line\"><strong>Non-weight bearing  </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 25 year old woman has presented to the ED with severe chest pain and shortness of breath. You are considering the diagnosis of pulmonary embolism (PE). She is pregnant at 18/40 gestation.","parts":[{"id":"a","label":"Part A","prompt":"State the pros and cons of the following investigations in the diagnosis of PE in this patient. (6 marks) Investigation Pros"},{"id":"b","label":"Part B","prompt":"dimer Cons Pros CTPA Cons Pros V/Q scan Cons Before definitive testing can be performed, the patient has the following vital signs:\n\nGCS\nPulse 145 /min\n\nBP\n70/45 mmHg\n\nRR\n/min O2 sats 96% 15L O2 via non-rebreather mask She is too unwell to leave the resus room. You have decided to perform a bedside echocardiogram to assess for PE."},{"id":"c","label":"Part C","prompt":"List 3 signs on bedside echocardiogram that would support the diagnosis of PE. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ Following your assessment, you are confident that the patient has a massive pulmonary embolism."},{"id":"d","label":"Part D","prompt":"List 3 components of your management of this patient. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">D-dimer</div><div class=\"answer-line\">Pros: negative result lowers probability to below test threshold in low-intermediate probability</div><div class=\"answer-line\">Cons: False positive results common, negative result in high pre-test probability does not exclude PE</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pros: Negative scan excludes significant PE</div><div class=\"answer-line\">Cons: Radiation exposure to maternal breast tissue increases lifetime cancer risk</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Pros: Can reliably identify/exclude PE in patients with normal lungs, at lower radiation risk to</div><div class=\"answer-line\">maternal breast tissue</div><div class=\"answer-line\">Cons: Risk of indeterminate result leading to need for CTPA, difficult to interpret in non-normal</div><div class=\"answer-line\">lungs, availability.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Analgesia – IV fentanyl 25mcg titrated to comfort</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 31 year old woman has been brought to the ED with erratic behaviour.","parts":[{"id":"a","label":"Part A","prompt":"List 6 features of your mental status examination that would be consistent with mania as a cause for her behaviour. (6 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ 6) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 3 outcomes of your initial assessment that would suggest that the patient is safe for formal psychiatric assessment without the need for further medical investigation. (3 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ During your initial assessment, the patient expressed a desire to leave the hospital."},{"id":"c","label":"Part C","prompt":"State 3 principles that must be met in order to detain the patient involuntarily. (3 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Pressured speech</div><div class=\"answer-line\">Grandiosity</div><div class=\"answer-line\">Decreased need for sleep</div><div class=\"answer-line\">Flight of ideas/racing thoughts</div><div class=\"answer-line\">Psychomotor agitation</div><div class=\"answer-line\">Distractibility</div><div class=\"answer-line\">Disinhibition (ie sexual, financial)</div><div class=\"answer-line\">Lack of restraint in goal driven pursuits</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">History of mania / bipolar</div><div class=\"answer-line\"><strong>Normal physical examination incl. vital signs </strong></div><div class=\"answer-line\">No evidence of pregnancy</div><div class=\"answer-line\">No signs intoxication</div><div class=\"answer-line\">Orientated</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Impaired capacity</div><div class=\"answer-line\">No less restrictive means to provide assessment/treatment</div><div class=\"answer-line\">Able to provide treatment at that facility</div><div class=\"answer-line\">Patient at risk to themselves or others</div><div class=\"answer-line\">Others likely acceptable here</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 50 year old man has been brought to the ED one hour after an unspecified overdose.\nHis ECG is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State the most likely class of drug responsible. Include 2 abnormalities from the ECG that support your conclusion. (3 marks)"},{"id":"b","label":"Part B","prompt":"State 5 clinical features that would be consistent with severe toxicity of this agent.\n(5 marks) The patient has life-threatening toxicity."},{"id":"c","label":"Part C","prompt":"List 3 end-points you would aim for in the resuscitation of this man. State how you will\nachieve each end-point. (6 marks) End point Management"}],"propPages":["asset:imgbe3083288edf21335c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>10/14</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Likely TCA overdose</div><div class=\"answer-line\">Terminal Rightward axis – terminal R in aVR</div><div class=\"answer-line\">Very broad QRS</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Seizures</div><div class=\"answer-line\">Delirium</div><div class=\"answer-line\">Coma</div><div class=\"answer-line\">Hypotension</div><div class=\"answer-line\">Ventricular Arrhythmias</div><div class=\"answer-line\">Anticholinergic effects</div><div class=\"answer-line\">Tachycardia</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">QRS narrowing &lt;100ms – NaHCO3 therapy to achieve narrowing</div><div class=\"answer-line\">SBP &gt;100mmHg – IV crystalloid loading 10-20ml/kg repeated</div><div class=\"answer-line\"><strong>pH &gt;7.50 intubation &amp; hyperventilation; NaHCO3 </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"An 18 year old carpentry apprentice has presented to the ED after an angle grinder blade shattered at work and hit her left eye. A photograph of her left eye is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 3 abnormalities in the photo. (3 marks)"},{"id":"b","label":"Part B","prompt":"State your diagnosis. (1 mark)"},{"id":"c","label":"Part C","prompt":"State 6 components of your management of this patient. (6 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ 6) ________________________________________________________________________________"}],"propPages":["asset:img1e3fdfcc3ced0c0330"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Irregular pupil</div><div class=\"answer-line\">Hyphaema</div><div class=\"answer-line\">Pupil midsize under light</div><div class=\"answer-line\">Conjunctival injection</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Penetrating Eye Injury</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">ADT</div><div class=\"answer-line\"><strong>Eye Shield </strong></div><div class=\"answer-line\">Analgesia</div><div class=\"answer-line\">Antiemetics</div><div class=\"answer-line\">Sit up</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 44 year old man has been referred by his GP with hypertension.\nOn arrival, the patient’s blood pressure is 230/120mmHg.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of your examination that would be consistent with hypertensive\nencephalopathy. (4 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 3 causes of secondary hypertension from separate organ systems. State how you will\nevaluate for the presence of each potential cause. (6 marks) Cause Evaluation Your assessment is consistent with hypertensive encephalopathy. The patient has a severe headache."},{"id":"c","label":"Part C","prompt":"State 3 key aspects of your blood pressure management. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/13</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Agitation</div><div class=\"answer-line\">Confusion</div><div class=\"answer-line\">Vomiting</div><div class=\"answer-line\">Coma</div><div class=\"answer-line\">Papilloedema</div><div class=\"answer-line\">Clonus</div><div class=\"answer-line\">hyperreflexia</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Vascular:</td><td>Renal Artery Stenosis - Ultrasound</td></tr><tr><td>Renal:</td><td>Intrinsic Renal disease ie PCKD – Renal Ultrasound</td></tr><tr><td colspan=\"2\">Renal tumours (ie those producing Renin) ie RCC, Wilms tumour - Ultrasound</td></tr><tr><td>Endocrine:</td><td>Adrenal Tumours – Urinary metanephrines, Triple Phase CT Abdomen</td></tr><tr><td colspan=\"2\">Conn’s Syndrome – high Na/low K</td></tr><tr><td colspan=\"2\">Cushing Syndrome – high cortisol</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia – most things OK</div><div class=\"answer-line\">BP control – some sort of parenteral agent with dose</div><div class=\"answer-line\">Target no more than 25% reduction</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 65 year old man has presented with a painful right knee.\nThere is no history of trauma.\nHe has a history of type 2 diabetes mellitus, hypertension and atrial fibrillation.\nA photograph of the patient’s knee is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 3 abnormalities from the photograph. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 4 differential diagnoses for this presentation. For each, state a diagnostic finding on joint aspirate. (8 marks) Diagnosis Joint aspirate findings\nPAH 2020.2 trial SAQ paper\nPART 3\nQuestions 19 - 27\n1 hour"}],"propPages":["asset:imgcf0c183089be5434a3"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Right knee erythema</div><div class=\"answer-line\">Prepatellar swelling</div><div class=\"answer-line\">Suprapatellar swelling</div><div class=\"answer-line\">Held in mid-flexion</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Septic Arthritis – organisms on gram stain</td><td>Gout – negatively birefringent crystals</td></tr><tr><td>Pseudogout – calcium pyrophosphate crystals</td><td>Haemarthrosis – frank blood on aspirate</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 27 year-old female has presented with severe epigastric pain.\nFollowing your initial assessment your provisional diagnosis is acute pancreatitis.","parts":[{"id":"a","label":"Part A","prompt":"List 4 historical features that you would ask to clarify the possible cause of her\npancreatitis. (4 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 5 Ranson criteria (headings only, values not required) for the assessment of severity of pancreatitis on admission to hospital. (5 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ In consultation with the surgical team, you have elected to perform a CT scan of the abdomen. A slice of the CT scan is provided in the PROPS BOOKLET."},{"id":"c","label":"Part C","prompt":"List 3 abnormalities on the CT scan. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List 6 complications you would look for in the ED. (6 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ 6) ________________________________________________________________________________"}],"propPages":["asset:img359c16bfcdb62312de"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>12/18</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">History of diabetes</div><div class=\"answer-line\">Recent trauma</div><div class=\"answer-line\">Recent medication use ie steroids</div><div class=\"answer-line\">Prior episodes of pancreatitis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Age &gt;55</div><div class=\"answer-line\">WCC &gt;16</div><div class=\"answer-line\">BSL &gt;10</div><div class=\"answer-line\">LDH &gt;350</div><div class=\"answer-line\">AST &gt;250</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Oedematous pancreas</div><div class=\"answer-line\">Heterogenous areas ?necrosis</div><div class=\"answer-line\">Fat Stranding around pancreas</div><div class=\"answer-line\"><strong>Free Fluid in paracolic gutter (Rt) and Perisplenic fluid (Lt) (only 1 mark for these) </strong></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Splenic Vein Thrombosis</div><div class=\"answer-line\">Ileus</div><div class=\"answer-line\">Third Spacing and hypovolaemia</div><div class=\"answer-line\">Haemorrhagic Shock – Hypotension</div><div class=\"answer-line\">Saponification with hypocalcaemia</div><div class=\"answer-line\">Respiratory Embarrasment</div><div class=\"answer-line\">Pleural Effusion</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"Your ED has been utilising a separate stream for the management of patients presenting to triage with possible COVID-19 virus infection. Due to increased costings, your hospital executive has asked you to review this process. They have suggested that it would be appropriate to return to a pre-pandemic model of care with precautions when indicated.","parts":[{"id":"a","label":"Part A","prompt":"State 5 factors you would consider in this review. (5 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 3 advantages and 3 disadvantages of returning to a pre-pandemic model of care.\n(6 marks) Advantages 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Current burden of cases going through Covid stream (ie bed occupancy COVID area)</div><div class=\"answer-line\">Community disease burden</div><div class=\"answer-line\">Suitability of areas within usual department to manage patients on precautions</div><div class=\"answer-line\">Access to rapid testing</div><div class=\"answer-line\">Impact of loss of general business beds upon flow of non-COVID patients</div><div class=\"answer-line\">Current advice from public health/Infection Control/Infectious Diseases</div><div class=\"answer-line\">Effectiveness of these models of care at peer sites</div><div class=\"answer-line\">Suitable area to ‘ramp’ COVID cases if COVID streaming area dissolved – public health implications of</div><div class=\"answer-line\">this</div><div class=\"answer-line\">Staff concerns about caring for possible COVID cases in usual care areas (ie nurses caring for both</div><div class=\"answer-line\">general and COVPREC patients concurrently)</div><div class=\"answer-line\">Staff fatigue through ongoing use of COVID streaming area</div><div class=\"answer-line\">Impacts on leave/fair rostering through ongoing use of COVID stream</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>ADVANTAGES</td><td>Less out-of-hours staffing requirements</td><td>Better access to leave</td></tr><tr><td>Improved departmental visibility/oversight with all patients in main department</td><td>Less confusion for departmental visitors/inpatient teams/ambulance service</td><td>Decreased costs</td></tr><tr><td>There will be others….</td><td>DISADVANTAGES</td><td>Potential cross-contamination of patient care spaces</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"An 8 year old boy has fallen off a fence at school. He complains of severe arm pain.\nHis x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State the diagnosis demonstrated. (2 marks)"},{"id":"b","label":"Part B","prompt":"List 3 radiological abnormalities to support your diagnosis. (3 marks)"},{"id":"c","label":"Part C","prompt":"List 3 acute complications of this injury. For each, state the suggestive examination findings. (6 marks) Complication Examination findings"}],"propPages":["asset:img00af0c57f4dac45b61","asset:imgdff17d9e867683b103"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">(Gartland 3 – 1 mark) <strong>Supracondylar fracture</strong> of humerus</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Posterior Periosteum disrupted</div><div class=\"answer-line\">Posterior displacement of distal humeral fragment</div><div class=\"answer-line\">Visible posterior fat pad sign indicating blood in joint space</div><div class=\"answer-line\">Loss of anterior humeral line</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Brachial artery injury </strong>– distal pallor, weak/absent pulse</td><td>AIN injury – loss of ‘OK sign’</td></tr><tr><td>Median Nerve Injury – any reasonable sign here</td><td>Compartment Syndrome – increasing pain, pallor, paraesthesia in &gt;1 nerve distribution</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 12 month old child has been brought to the ED with stridor.\nYour provisional diagnosis is croup.","parts":[{"id":"a","label":"Part A","prompt":"List 4 differential diagnoses for this child’s stridor other than croup. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 4 clinical features that would be consistent with severe croup. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ The child is alert but clearly anxious. You have assessed the child as having severe croup."},{"id":"c","label":"Part C","prompt":"State 2 components of your specific treatment. (2 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"State 3 clinical criteria for discharge from the ED for this patient. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>10/13</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Bacterial Tracheitis</div><div class=\"answer-line\">Airway Foreign Body</div><div class=\"answer-line\">Severe tonsillitis or other upper airway obstruction</div><div class=\"answer-line\">Airway oedema from anaphylaxis</div><div class=\"answer-line\">Vascular rings</div><div class=\"answer-line\">Tracheomalacia</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Stridor at rest</div><div class=\"answer-line\">Agitation</div><div class=\"answer-line\">Chest wall retraction/accessory muscle use</div><div class=\"answer-line\">Altered Consciousness</div><div class=\"answer-line\">Decreased air entry</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Dexamethasone 0.6mg/kg (accept anything from 0.15-0.6) IV/IM/PO or other steroid</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">No ongoing oxygen requirement</div><div class=\"answer-line\">Improved clinical features ie no stridor at rest/improved WOB</div><div class=\"answer-line\">Tolerating oral intake</div><div class=\"answer-line\">Adequate hydration status</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 27 year old man has been brought to the ED with a history of abdominal pain and vomiting. A venous blood gas has been provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List the 2 most significant metabolic processes present. For each, provide relevant\ncalculations and an explanation of the likely cause. (6 marks) Metabolic process Relevant calculations Likely cause"},{"id":"b","label":"Part B","prompt":"List and justify 4 further investigations you would perform. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ The patient has the following vital signs:\n\nGCS\nE3 V4 M6 Pulse 135 /min\n\nBP\n80/40 mmHg Temperature 36.5 degrees\n\nRR\n/min O2 sats 98% room air"},{"id":"c","label":"Part C","prompt":"State 5 therapeutic interventions you would anticipate using in the first 6 hours. Include end-points where appropriate. (5 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________"}],"propPages":["asset:imgfc7c6bb4755bfb03e4"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/15</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Two most significant metabolic processes:</td><td>1 <strong>– HAGMA</strong> – Anion Gap 133 – (82+22) = 29</td></tr><tr><td>Likely cause – ketones (ie <strong>DKA</strong>) other causes would be renal acids or toxic alcohols however lactate</td><td>not significantly raised cf AG</td></tr><tr><td>2 -  Metabolic Alkalosis – Delta Gap = Change in AG (17) / change in HCO3 = 2 = 8.5 = indicates</td><td>concurrent Metabolic Alkalosis (other cause for raised delta gap &gt;1 would be concurrent resp</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Ketones – identify DKA</div><div class=\"answer-line\">Chem20/EUC etc -  identify renal failure</div><div class=\"answer-line\">Lipase – as cause of abdominal pain/vomiting</div><div class=\"answer-line\">CXR – exclude causative findings ie RLL pneumonia or complications ie aspiration</div><div class=\"answer-line\">Other investigations for sepsis – ie urine MCS, blood cultures likely ok, FBE not accepted unless well</div><div class=\"answer-line\">justified, ECG similarly</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>- IV fluid replacement</strong> -  given shock for fluid bolus initially ie 0.9% saline 10-20mls/kg aim SBP &gt;100</div><div class=\"answer-line\"><strong>- IV Insulin infusion</strong> – 0.1u/kg/hr to 6u/hr or similar – to terminate ketosis</div><div class=\"answer-line\">- Antiemetics – vomiting ie ondansetron 0.15mg/kg to 8mg q8h to termination of vomiting</div><div class=\"answer-line\">- Analgesia -  IV fentanyl or similar 0.5 mcg/kg to comfort</div><div class=\"answer-line\">- Potassium replacement – once K&lt;5 and insulin infusion running, aim to maintain K&gt;4.0</div><div class=\"answer-line\">- Sugar replacement ie 5% dextrose IV infusion once BSL &lt;15 to maintain BSL in normoglycaemic</div><div class=\"answer-line\">range</div><div class=\"answer-line\">- IV Antibiotics for empiric sepsis ie flucloxacillin 2gm + gentamicin 5-7mg/kg +/- Vancomycin</div><div class=\"answer-line\">30mg/kg for empiric sepsis management if no clear cause found for haemodynamic status or focal</div><div class=\"answer-line\">sepsis</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"You have been called by a nurse working on a popular North Queensland holiday island. She is seeking advice for a male patient in his 60s who has collapsed shortly after ascending from a scuba diving expedition.","parts":[{"id":"a","label":"Part A","prompt":"List 4 diving related pathologies you would consider as a cause for his collapse. (4 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 4 non-diving related pathologies you would consider as a cause for his collapse.\n(4 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ The patient is confused and has difficulty breathing. You feel the patient has diving related pathology and requires retrieval to your hospital. The nurse has asked your advice on how to manage the patient who will require a 30 minute helicopter flight."},{"id":"c","label":"Part C","prompt":"State 3 components of your management advice. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Brain</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Spinal cord syndromes</div><div class=\"answer-line\">Pulmonary Barotrauma</div><div class=\"answer-line\">Oxygen toxicity</div><div class=\"answer-line\">Water aspiration</div><div class=\"answer-line\">Nitrogen Narcosis</div><div class=\"answer-line\">Hypoxia from empty tanks</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Marine Envenomation</div><div class=\"answer-line\">Acute Coronary Syndrome with arrythmia</div><div class=\"answer-line\">Hypothermia</div><div class=\"answer-line\">Fatigue</div><div class=\"answer-line\">Head Injury</div><div class=\"answer-line\">Seizure from pre-existing cause ie epilepsy</div><div class=\"answer-line\">Many ok answers here</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Lie patient flat</div><div class=\"answer-line\"><strong>High flow oxygen for de-nitrogenation </strong></div><div class=\"answer-line\">IV fluids to maintain circulatory volume</div><div class=\"answer-line\">Antiemetics/Analgesia likely ok here</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 74 year old woman has presented to your tertiary ED with a left hemiplegia. You are concerned about the possibility of an ischaemic stroke and have ordered an urgent CT perfusion scan. She is a current smoker with no other known medical issues.","parts":[{"id":"a","label":"Part A","prompt":"List 4 findings on a CT perfusion scan that would support urgent reperfusion therapy.\n(4 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ Following a full assessment and upon reviewing the CT results, the stroke consultant has recommended thrombolysis for this patient. The patient has capacity for consent."},{"id":"b","label":"Part B","prompt":"Complete the table with details you would convey during the discussion around consent for thrombolysis. (3 marks) Component Detail Risk of intracranial haemorrhage Overall mortality benefit Reported benefit of thrombolysis Thrombolysis has been initiated. A bolus of alteplase was given and the patient commenced on a 60\nminute infusion. At the 30 minute mark, the patient has large volume haematemesis.\nThe patient’s vital signs are:\n\nGCS\nE4 V5 M6 (with hemiplegia) Pulse 135 /min\n\nBP\n75/45 mmHg\n\nRR\n/min O2 sats 99% room air"},{"id":"c","label":"Part C","prompt":"State 5 components of your further management. (5 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>6/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Absence of haemorrhage</div><div class=\"answer-line\">Evidence of large vessel occlusion</div><div class=\"answer-line\">Small ischaemic core</div><div class=\"answer-line\">Large ischaemic penumbra</div><div class=\"answer-line\">No signs of completed stroke ie oedema, loss of grey-white differentiation</div><div class=\"answer-line\">No contraindications to thrombolytics ie presence of AVM/brain tumour/unsecured aneurysm</div><div class=\"answer-line\">&gt;10mm (ok I’m stretching a bit here)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">7% risk of ICH (3% fatal)</div><div class=\"answer-line\">No overall mortality benefit</div><div class=\"answer-line\">Small but significant chance of improved neurologic outcomes at 90d</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Cease infusion of tPA</div><div class=\"answer-line\">IV TXA 30mg/kg</div><div class=\"answer-line\">IV Fibrinogen 3gm (some dose variation here) – up to 50mg/kg</div><div class=\"answer-line\">Blood transfusion to replace volume – 10mls/kg packed cells to SBP &gt;100/MAP &gt;65</div><div class=\"answer-line\">Urgent Gastroenterology involvement for scope +/- intervention</div><div class=\"answer-line\">IV PPI bolus + infusion</div><div class=\"answer-line\">Others might be ok here</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A ten month old girl has been brought to the ED with profuse vomiting for the last day. The patient was born at term and has no known medical conditions.","parts":[{"id":"a","label":"Part A","prompt":"List 3 surgical causes of vomiting. Indicate the examination findings that would support\neach cause. (6 marks) Surgical cause Examination findings"},{"id":"b","label":"Part B","prompt":"List 4 investigations you might perform. For each, list the clinical indication for its use. (4 marks) Investigation Clinical indication Your clinical assessment is consistent with gastroenteritis and moderate dehydration. The child is unable to tolerate oral fluid."},{"id":"c","label":"Part C","prompt":"State 3 components of your nasogastric rapid rehydration management. (3 marks)\nFluid Rate Duration"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/13</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Incarcerated hernia</td></tr><tr><td>-</td><td>Palpable, tender hernia (inguinal, umbilical)</td></tr><tr><td colspan=\"2\">Appendicitis</td></tr><tr><td>-</td><td>Tender RIF with peritonism on exam, febrile</td></tr><tr><td colspan=\"2\">Biliary Atresia</td></tr><tr><td>-</td><td>Jaundice</td></tr><tr><td colspan=\"2\">Malrotation Syndromes</td></tr><tr><td>-</td><td>Bilious vomiting</td></tr><tr><td colspan=\"2\">Small Bowel Obstruction -</td></tr><tr><td>-</td><td>Intussusception – pale, floppy episodes</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>VBG – check electrolytes (particularly Na, K), anion gap and lactate.  Indication – poor perfusion,</td><td>impaired mentation, or tone</td></tr><tr><td>Blood Cultures – Febrile with no clear focus to guide therapy</td><td>Abodminal Ultrasound – tenderness/mass on exam</td></tr><tr><td>LFTs – clinical jaundice</td><td>AXR – shocked child looking for pneumatosis, perforation</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Fluid – ORS/Pedialyte/Hydralyte</div><div class=\"answer-line\">Rate – 25ml/kg/hr for 4 hours ie for 10mth old 250ml/hr</div><div class=\"answer-line\">Duration – 4 hrs</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 34 year old man has presented with left thumb and hand pain following a fish hook injury yesterday. A photograph is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 4 abnormalities from the photograph. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ You are concerned about the possibility of necrotising fasciitis."},{"id":"b","label":"Part B","prompt":"Apart from the features mentioned in Q1, list 3 clinical features that would support this diagnosis. (3 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"List 3 pathogens known to cause necrotising fasciitis. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ The patient has necrotising fasciitis."},{"id":"d","label":"Part D","prompt":"State the 2 most important components of your management. (2 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________"}],"propPages":["asset:img4d275b693292fa2d6e"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Puncture wound over IPJ of Left thumb</div><div class=\"answer-line\">Distal swelling and bruising over distal phalanx</div><div class=\"answer-line\">Oedema to entire visible hand</div><div class=\"answer-line\">Erythema to entire visible hand</div><div class=\"answer-line\">Tracking crossing carpus and extending proximally</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Clinical features of severe sepsis ie hypotension</div><div class=\"answer-line\">Crepitus on exam</div><div class=\"answer-line\">Severe Pain</div><div class=\"answer-line\">Gas in soft tissues on xray</div><div class=\"answer-line\">Rapid spread of tracking cellulitis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Group A Strep (pyogenes)</div><div class=\"answer-line\">Staph Aureus</div><div class=\"answer-line\">Enterococcus</div><div class=\"answer-line\">E.Coli</div><div class=\"answer-line\">Pseudomonas Aeruginosa</div><div class=\"answer-line\">Bacteroides</div><div class=\"answer-line\">Clostridial Species</div><div class=\"answer-line\">Vibrio Vulnificus</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Antibiotics – Meropenem 1gm/Piptaz 4.5gm + Vancomycin 30mg/kg + Clinda/Linco 600mg</div><div class=\"answer-line\">Aggressive surgical debridement</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
